-- Preserve every attendance event. Replace calendar-day uniqueness with a rolling service lock.
BEGIN;
ALTER TABLE "Employee" ADD COLUMN "lastSuccessfulAttendanceAt" TIMESTAMP(3);
ALTER TABLE "AttendanceRecord" ADD COLUMN "registeredAt" TIMESTAMP(3);
-- QR originalCheckInAt was generated by the server and is preserved by corrections.
-- Include soft-deleted QR events: deleting/correcting a record must not bypass cooldown.
UPDATE "AttendanceRecord"
SET "registeredAt" = COALESCE("originalCheckInAt", "createdAt")
WHERE "registrationMethod" = 'QR';
UPDATE "Employee" e SET "lastSuccessfulAttendanceAt" = history.latest
FROM (SELECT "employeeId", MAX("registeredAt") AS latest FROM "AttendanceRecord"
      WHERE "registrationMethod" = 'QR' GROUP BY "employeeId") history
WHERE e."id" = history."employeeId";
CREATE INDEX "AttendanceRecord_employeeId_registeredAt_idx" ON "AttendanceRecord"("employeeId", "registeredAt");
DROP INDEX "AttendanceRecord_active_employee_date";
COMMIT;
